UPDATE mall_activity_goods
SET sold_count = sold_count + #{quantity}
WHERE activity_id = #{activityId}
  AND spec_id = #{specId}
  AND (activity_stock - sold_count) >= #{quantity}

UPDATE mall_activity_goods
SET sold_count = sold_count - #{quantity}
WHERE activity_id = #{activityId}
  AND spec_id = #{specId}
  AND sold_count >= #{quantity}
